#!/usr/bin/env bash
# Every function's description and grants, in one place. Regenerates
# functions/<name>/<name>.json; never edit those by hand (bin/fnjson.py, as Triage's).
#   table   read        table:rw  + write rows        table:rwd  + delete rows
#   function:<name>     run it        workflow:<name>     start and read its runs
#   connector:<id>      use it        /folder:verbs       a folder
#   pod:<permission>    a pod-wide permission (channel.notify_self, channel.read)
# No function can be granted schedule.create, a table's visibility, a folder's
# access, opening a function to contacts, contact outreach or a notice to
# another member, so those are done by the app as the person (README, "What
# only a person can do").
set -euo pipefail
cd "$(dirname "$0")/.."
f() { uv run --no-project python bin/fnjson.py "$@"; }
READ="knowhow_settings knowhow_topic knowhow_person knowhow_correction"
ANSWER="$READ knowhow_article:rw knowhow_question:rw knowhow_my_question:rw knowhow_event:rw /know-how:read"
f knowhow_answer "Answer a member's how, what, when or policy question from the team's pages (question: their words; source: teams, slack, email, web or app; place; channel_id or conversation_id; asker_name). Returns the page that answers, with the exact source line to say ('From Lead times, checked by Priya Raman on 3 Nov.') and a warning when it's past its check date. Logs the question; on a miss, names the topic's owner and how to ask them. Call it before searching other files; never invent what a page doesn't say." $ANSWER
f knowhow_answer_for_contact "For a customer (a contact on email, Slack Connect or the web chat): answers only from the team's checked, in-date answers meant for customers. Call it before answering any question about products, orders, policies or how to do something, and never guess. When it says pass_to_person, call ask_a_person and tell the customer a person will answer. Give only what the answer says, with its source line." $ANSWER
f knowhow_missing "An explicit miss: the page didn't fit, the asker said an answer was wrong (wrong, article_id), or a question asked mid-walk (walk_id, step). Logs it with its topic and repeats, and returns the owner and how they want to be asked: when ask_by is teams, ask them with channel_post, with the earlier askings, and wait." $ANSWER knowhow_walk knowhow_correction:rw
f knowhow_draft "Turn an owner's reply into a draft page they save in one step (question_ids, reply word for word, reply_who, reply_where). With body_md it's saved as written; without, the writer drafts it from the reply and the questions. With article_id and step (a question asked mid-walk) it becomes a proposed change to that step. Call it when the owner's reply comes back." $READ knowhow_article:rw knowhow_question:rw knowhow_change:rw knowhow_event:rw /know-how:read,write workflow:knowhow-draft
f knowhow_decide "A person's decision in the Know-how app (action: save, edit, covered_by, set_aside, ask_owner, ask_check, keep, retire, approve_for_customers, take_back, add_change, decline_change, record). Never call it for the team unless a person decided." $READ knowhow_article:rw knowhow_question:rw knowhow_change:rw knowhow_event:rw knowhow_correction:rw article:rwd /know-how:read,write,delete
f knowhow_publish "Copy live public pages into the shared article table, or take out any that may no longer be there (article_id for one page; empty for all)." knowhow_settings knowhow_topic knowhow_article:rw article:rwd /know-how:read
f knowhow_unpublish "Take one page's copy out of the shared article table (article_id)." knowhow_article:rw article:rwd knowhow_event:rw
f knowhow_tell "Who to tell that their question has an answer (mode list, article_id), or mark them told (mode mark, question_ids, how). The app tells them as the person." knowhow_question:rw knowhow_event:rw
f knowhow_walk "Walk someone through a procedure one step at a time (action start with text: their words or article_id; done, stuck, question with text, stop, with walk_id). Show its say text, then ask_user with Done, I'm stuck, Stop, and wait for Done before the next step. A question mid-walk goes to the owner and the walk carries on." $ANSWER knowhow_walk:rw knowhow_assignment:rw
f knowhow_assign "Assign a procedure to members (article_id, members: [{member_id, name}], role, due_on), or take one off (unassign_id)." knowhow_article knowhow_assignment:rwd knowhow_event:rw
f knowhow_from_thread "Make a draft procedure (or answer) from a thread when someone says 'make this a procedure' (thread: its text, link, where, title, kind). Read the Teams or Slack thread first and pass its text." $READ knowhow_article:rw knowhow_question knowhow_event:rw /know-how:read,write function:knowhow_draft
f knowhow_read_source "What's new in Know-how's sources for the reader: uploaded files (sheets become table pages beside them; slides, images and IES files are named as unsearchable), a website, a Google Drive folder. Returns one reading brief." knowhow_settings knowhow_topic knowhow_source:rw knowhow_article:rw knowhow_event:rw /know-how:read,write connector:googledrive
f knowhow_reader_save "Keep knowhow_reader's proposals: draft pages under /know-how/_drafts/, proposed topics for set-up, files it couldn't read." knowhow_settings:rw knowhow_topic knowhow_person knowhow_source:rw knowhow_article:rw knowhow_question:rw knowhow_event:rw /know-how:read,write
f knowhow_setup_apply "Set-up's 'Who knows what?': write the topics (owner, backup, check interval, who may see it, sensitive), make their folders, and file the reader's drafts under them. Safe to run again." knowhow_settings knowhow_topic:rw knowhow_article:rw /know-how:read,write
f knowhow_setup_save "Keep Know-how's set-up (only the fields given): places, audiences, approver, check interval, time zone, what the app made; done finishes set-up and writes the memory block. Safe to run again." knowhow_settings:rw function:knowhow_memory
f knowhow_me_save "One person's Know-how preferences: how to ask them about a miss (teams or today), daily or weekly checks and the day, their schedule's name." knowhow_settings knowhow_person:rw
f knowhow_memory "Tells this Lemma's agents that Know-how is installed: its own block in /memory/AGENTS.md and its guide at /memory/plugins/know-how.md, leaving the team's notes alone. Set-up runs it; safe to run again. remove takes both out." /memory:read,write
f knowhow_check "Daily upkeep: pages past their check date, public answers out of the shared article table on their due day, pages whose file or source changed checked for disagreement, sheet pages made again, uses counted (as_of to run as if on another day)." knowhow_settings:rw knowhow_topic knowhow_article:rw knowhow_change:rw knowhow_question knowhow_walk knowhow_source knowhow_event:rw knowhow_correction article:rwd /know-how:read,write workflow:knowhow-read-sources
f knowhow_mine "What in Know-how needs the person running this, in the shared needs_you list (Today reads it): misses in their topics, drafts to save, proposed changes, answers past their check date, customer answers about to leave, procedures assigned to them. Tells them when their own questions have an answer. Runs as the person." knowhow_settings knowhow_topic knowhow_person knowhow_article knowhow_question:rw knowhow_my_question:rw knowhow_change knowhow_assignment knowhow_event:rw needs_you:rw pod:channel.notify_self
f knowhow_sweep "Daily safety net (the knowhow-sweep workflow): brief gives the topics and what is already logged; log takes the question-like lines the assistant found in the last day's group and customer chats (lines: [{text, message_id, channel_id, source, place, sender_name, sender_kind}]) and logs the ones in Know-how's topics as missed, for their owner." $READ knowhow_article knowhow_question:rw knowhow_my_question:rw knowhow_event:rw
f knowhow_on_slack "A new message in a watched Slack channel (the channel trigger): a question is logged and answered or missed; a reply that answers a logged miss in its thread becomes a draft for the owner." $ANSWER function:knowhow_draft
f knowhow_sample_data "load: a sample Wednesday at Fernlow Lighting to look around (six topics, twenty real pages, 48 questions this month, drafts, a page that may disagree, a walk; made-up people at .example addresses, nothing posted outside). clear: removes only what the sample made." knowhow_settings:rw knowhow_topic:rwd knowhow_article:rwd knowhow_question:rwd knowhow_change:rwd knowhow_source:rwd knowhow_walk:rwd knowhow_assignment:rwd knowhow_event:rwd knowhow_sample_row:rwd knowhow_person article:rwd needs_you:rw /know-how:read,write,delete function:knowhow_mine
